7	/// Trait for durable changeset and manifest storage operations.
8	pub trait ChangesetStorage {
9	    /// Writes content atomically with parent and grandparent directory journal flushing.
10	    ///
11	    /// # Errors
12	    ///
13	    /// Returns `Err` on any I/O failure: directory creation, temp-file creation, write, sync, or persist.
14	    fn atomic_write_durable(&self, content: &str, permit: &ApplyPermit) -> io::Result<()>;
15	}
16	
17	impl ChangesetStorage for Path {
18	    fn atomic_write_durable(&self, content: &str, permit: &ApplyPermit) -> io::Result<()> {
19	        atomic_write(self, content, permit)
20	    }
21	}
22	
23	/// Durably replaces `path`'s contents with `content`.
24	///
25	/// The [`ApplyPermit`] is unused at runtime and exists purely as a compile-time
26	/// obligation: this is callisto's single disk-write primitive, so requiring a
27	/// permit here means no code path can reach the filesystem without having first
28	/// consulted the dry-run flag. See [`callisto_model::permit`].
29	///
30	/// # Errors
31	///
32	/// Returns the first I/O error encountered: creating parent directories, writing the temp file,
33	/// flushing, fsyncing, or persisting (renaming) to `path`.
34	pub fn atomic_write(path: &Path, content: &str, permit: &ApplyPermit) -> io::Result<()> {
35	    let _permit = permit;
36	    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
37	    let parent = if raw_parent.as_os_str().is_empty() {
38	        Path::new(".")
39	    } else {
40	        raw_parent
41	    };
42	    std::fs::create_dir_all(parent)?;
43	
44	    let mut temp = NamedTempFile::new_in(parent)?;
45	    temp.write_all(content.as_bytes())?;
46	    temp.flush()?;
47	    temp.as_file().sync_all()?;
48	    temp.persist(path).map_err(|e| e.error)?;
49	
50	    if let Ok(parent_file) = std::fs::File::open(parent) {
51	        let _res = parent_file.sync_all();
52	    }
53	    if let Some(grandparent) = parent.parent() {
54	        if !grandparent.as_os_str().is_empty() {
55	            if let Ok(gp_file) = std::fs::File::open(grandparent) {
56	                let _res = gp_file.sync_all();
57	            }
58	        }
59	    }
60	    Ok(())
61	}
