41	impl<'r> GitAccess<'r> {
42	    /// Tries to discover a native `gix` repository at `root`; regardless of
43	    /// whether that succeeds, also prepares the `CommandRunner`-shelled
44	    /// backend against the same `root`, ready to serve as a fallback (reads)
45	    /// or as the sole backend (writes, when discovery failed).
46	    ///
47	    /// Never fails: a discovery failure just means every operation runs
48	    /// through the shell backend instead, exactly as it unconditionally
49	    /// does on `wasm32` (gix is excluded from that target's dependency set,
50	    /// so [`GitRepository::discover`] always returns `Err` there).
51	    pub fn discover(root: impl AsRef<Path>, runner: &'r dyn CommandRunner) -> Self {
52	        let root = root.as_ref();
53	        GitAccess {
54	            native: GitRepository::discover(root).ok(),
55	            shell: ShellGit::new(runner, root.to_path_buf()),
56	        }
57	    }
58	}
