14	/// Fetches commits reachable from `HEAD` (down to `window`'s lower bound,
15	/// exclusive), scoped to those touching at least one of `pathspecs`.
16	///
17	/// Delegates entirely to [`GitAccess`], which tries native gix discovery
18	/// first (cheap and side-effect-free) and falls back to a `CommandRunner`-
19	/// shelled `git log --no-merges` when gix is unavailable -- most notably on
20	/// `wasm32`, where gix is excluded from that target's dependency set. Either
21	/// way the result comes back as the same `callisto_vcs::GitCommit` shape,
22	/// so the raw-message reconstruction and conventional-commit parsing below
23	/// runs identically regardless of which backend served the request.
24	pub fn fetch_commits(
25	    runner: &dyn CommandRunner,
26	    cwd: &Path,
27	    window: &InferenceWindow,
28	    pathspecs: &[PathBuf],
29	) -> Result<Vec<ParsedCommit>, ConventionalError> {
30	    let since_ref = match window {
31	        InferenceWindow::SinceCommit(sha) => Some(sha.as_str().to_string()),
32	        InferenceWindow::FullHistory => None,
33	    };
34	
35	    let git = GitAccess::discover(cwd, runner);
36	    let commits = git.commits_since(since_ref.as_deref(), pathspecs)?;
37	
38	    Ok(commits
39	        .into_iter()
40	        .map(|c| {
41	            let message = match c.body {
42	                Some(body) => format!("{}\n\n{}", c.summary, body),
43	                None => c.summary,
44	            };
45	            parse_commit(c.sha, &message)
46	        })
47	        .collect())
48	}
