use gix_odb::HeaderExt as _;

fn main() {
    let cwd = std::env::current_dir().unwrap();
    let git_dir = cwd.join(".git");
    println!(".git exists: {}", git_dir.exists());

    let odb = gix_odb::at(git_dir.join("objects")).unwrap();
    println!("gix-odb opened OK");

    let ref_store = gix_ref::file::Store::at(
        git_dir.clone(),
        gix_ref::store::init::Options {
            object_hash: gix_hash::Kind::Sha1,
            ..Default::default()
        },
    );
    println!("gix-ref opened OK");

    let head_ref = ref_store.find("HEAD").unwrap();
    let head_id = match head_ref.target {
        gix_ref::Target::Object(id) => id,
        gix_ref::Target::Symbolic(name) => {
            ref_store.find(name.as_bstr()).unwrap()
                .target.try_id().unwrap().to_owned()
        }
    };
    println!("HEAD: {head_id}");

    let header = odb.header(head_id.as_ref()).unwrap();
    println!("object kind: {:?} size: {}", header.kind(), header.size());
    println!("PROBE SUCCESS");
}
