357	    fn publish_with_retry(
358	        &self,
359	        pkg_id: &PackageId,
360	        version: &Version,
361	        permit: &ApplyPermit,
362	    ) -> Result<PublishOutcome, RegistryError> {
363	        if self.client.is_published(pkg_id, version)? {
364	            return Ok(PublishOutcome::AlreadyPublished);
365	        }
366	
367	        loop {
368	            match self.client.publish(pkg_id, version, permit) {
369	                // Both a fresh publish and a publish-time "already there"
370	                // classification are done-and-not-an-error: neither should
371	                // retry, and AlreadyPublished is treated identically to the
372	                // is_published short-circuit above.
373	                Ok(outcome @ (PublishOutcome::Published | PublishOutcome::AlreadyPublished)) => {
374	                    return Ok(outcome)
375	                }
376	                Err(RegistryError::RateLimited(retry_after)) => {
377	                    if retry_after > Duration::from_secs(600) {
378	                        return Err(RegistryError::RateLimited(retry_after));
379	                    }
380	                    self.policy.check_rate_limit(retry_after)?;
381	                    self.time.sleep(retry_after);
382	                }
383	                Err(RegistryError::AuthFailed(err)) => {
384	                    return Err(RegistryError::AuthFailed(err));
385	                }
386	                Err(err) => {
387	                    return Err(err);
388	                }
389	            }
390	        }
391	    }
392	}
