472	    fn publish_with_retry(
473	        &self,
474	        pkg_id: &PackageId,
475	        version: &Version,
476	        permit: &ApplyPermit,
477	    ) -> Result<PublishOutcome, RegistryError> {
478	        if self.client.is_published(pkg_id, version)? {
479	            return Ok(PublishOutcome::AlreadyPublished);
480	        }
481	
482	        let mut retries = 0usize;
483	        loop {
484	            match self.client.publish(pkg_id, version, permit) {
485	                // Both a fresh publish and a publish-time "already there"
486	                // classification are done-and-not-an-error: neither should
487	                // retry, and AlreadyPublished is treated identically to the
488	                // is_published short-circuit above.
489	                Ok(outcome @ (PublishOutcome::Published | PublishOutcome::AlreadyPublished)) => {
490	                    return Ok(outcome)
491	                }
492	                Err(RegistryError::RateLimited(retry_after)) => {
493	                    if retry_after > Duration::from_secs(MAX_RETRY_AFTER_SECS) {
494	                        return Err(RegistryError::RateLimited(retry_after));
495	                    }
496	                    retries += 1;
497	                    if retries > MAX_RATE_LIMIT_RETRIES {
498	                        return Err(RegistryError::Other(format!(
499	                            "rate-limited {} consecutive times; giving up",
500	                            retries
501	                        )));
502	                    }
503	                    self.policy.check_rate_limit(retry_after)?;
504	                    self.time.sleep(retry_after);
505	                }
506	                Err(RegistryError::AuthFailed(err)) => {
507	                    return Err(RegistryError::AuthFailed(err));
508	                }
509	                Err(err) => {
510	                    return Err(err);
511	                }
512	            }
513	        }
514	    }
515	}
