712	/// 1. Any `"already exist"` substring (from `--skip-existing`) →
713	///    [`PublishOutcome::AlreadyPublished`]. Partial skips (e.g. sdist
714	///    skipped, wheel uploaded) cannot be distinguished from a complete skip
715	///    by text alone, so any skip mention is conservatively classified as
716	///    already-published rather than over-reporting a fresh publish.
717	/// 2. Zero exit code with no skip mention → [`PublishOutcome::Published`].
718	/// 3. Rate-limit signal (`429`, `too many requests`, `rate limit`) →
719	///    [`RegistryError::RateLimited`] with a parsed or default 60-second
720	///    retry-after duration.
721	/// 4. Auth-failure signal (`401`, `403`, `authentication`, etc.) →
722	///    [`RegistryError::AuthFailed`].
723	/// 5. Anything else → [`RegistryError::Other`].
724	fn classify_twine_output(output: &CommandOutput) -> Result<PublishOutcome, RegistryError> {
725	    let combined = combined_lower(output);
726	
727	    if combined.contains("already exist") {
728	        return Ok(PublishOutcome::AlreadyPublished);
729	    }
730	    if output.success() {
731	        return Ok(PublishOutcome::Published);
732	    }
733	    if let Some(err) = detect_rate_limit(&combined) {
734	        return Err(err);
735	    }
736	    if let Some(err) = detect_auth_failure(&combined, &output.stderr) {
737	        return Err(err);
738	    }
739	    Err(RegistryError::Other(format!(
740	        "twine upload failed (exit {:?}): {}",
741	        output.exit_code,
742	        output.stderr.trim()
743	    )))
744	}
